# %% ../nbs/12_train_flow.ipynb #aa120003
class EmbeddingDataset(Dataset):
    """Load PCA-projected embeddings from chunk files produced by fit_pca.

    Each chunk file is a dict with keys 'L0', 'L1', ... each (N_chunk, D).
    Optionally loads raw preencode chunks (list of batch dicts) for the no-PCA path.

    Args:
        paths:   glob pattern, Path, or list thereof pointing to chunk .pt files
        levels:  list of level keys to use, e.g. ['L0','L1',...,'L5'].
                 If multiple levels given, concatenates along dim=1.
                 If None, uses all keys found in the first file.
        key:     for raw preencode chunks, which embedding key ('emb1','emb2','emb3')
        level:   for raw preencode chunks, which hierarchy level index
    """
    def __init__(self, paths, levels=None, key='emb2', level=0):
        import glob as _glob
        if isinstance(paths, (str, Path)): paths = [paths]
        all_files = []
        for p in paths:
            expanded = sorted(_glob.glob(str(p)))
            all_files.extend([Path(x) for x in expanded] if expanded else [Path(p)])

        all_embs = []
        for fp in all_files:
            data = torch.load(fp, weights_only=False)
            if isinstance(data, dict) and any(k.startswith("L") for k in data):
                # PCA chunk format: {'L0': (N,D), 'L1': (N,D), ...}
                lvls = levels or sorted(k for k in data if k.startswith("L"))
                tensors = [data[lv].float() for lv in lvls]
                if not hasattr(self, '_level_dims'):
                    self._level_dims = [t.shape[1] for t in tensors]
                all_embs.append(torch.cat(tensors, dim=1) if len(tensors) > 1 else tensors[0])
            elif isinstance(data, list):
                # Raw preencode chunk format
                for batch_rec in data:
                    emb = batch_rec[key][level]      # (B, N_patches, D)
                    all_embs.append(emb.mean(dim=1).float())
            else:
                raise ValueError(f"Unrecognised format in {fp}")
        self.embeddings = torch.cat(all_embs, dim=0)
        self.level_dims = getattr(self, '_level_dims', [self.embeddings.shape[1]])

    def __len__(self): return len(self.embeddings)
    def __getitem__(self, i): return self.embeddings[i]

# %% ../nbs/12_train_flow.ipynb #aa120004
class VelocityNet(nn.Module):
    """MLP velocity field for flow matching.  Input: [x, t], output: dx/dt.
    Hidden layers use residual (skip) connections."""
    def __init__(self, input_dim, h_dim=256, n_layers=3):
        super().__init__()
        self.fc_in  = nn.Linear(input_dim + 1, h_dim)
        self.hidden = nn.ModuleList([nn.Linear(h_dim, h_dim) for _ in range(n_layers - 1)])
        self.fc_out = nn.Linear(h_dim, input_dim)

    def forward(self, x, t):
        if t.dim() == 0: t = t.expand(x.size(0), 1)
        elif t.dim() == 1: t = t.unsqueeze(1)
        t = t.expand(x.size(0), 1)
        h = F.gelu(self.fc_in(torch.cat([x, t], dim=1)))
        for layer in self.hidden:
            h = F.gelu(layer(h)) + h  # residual connection
        return self.fc_out(h)

# %% ../nbs/12_train_flow.ipynb #behr6w8yrw7
class PerLevelFlowModel(nn.Module):
    """One VelocityNet per embedding level; each level's slice is routed to its own net.
    Has the same forward(x, t) interface as VelocityNet, so all training/eval code works unchanged.
    level_dims: list of ints, e.g. [16, 16, 16, 16, 16, 8] from dataset.level_dims
    """
    def __init__(self, level_dims, h_dim=256, n_layers=4):
        super().__init__()
        self.level_dims = level_dims
        self.nets = nn.ModuleList([VelocityNet(d, h_dim, n_layers) for d in level_dims])

    def forward(self, x, t):
        outs, offset = [], 0
        for net, d in zip(self.nets, self.level_dims):
            outs.append(net(x[:, offset:offset+d], t))
            offset += d
        return torch.cat(outs, dim=1)

# %% ../nbs/12_train_flow.ipynb #aa120005
def warp_time(t, s=0.5):
    """Parametric time warping (Scott H. Hawley, 'Flow With What You Know', ICLR 2025).
    s=1 → linear; s<1 → slower near middle; s=1.5 ≈ cosine schedule.
    Works on scalar, 1-D or 2-D tensors."""
    return 4*(1-s)*t**3 + 6*(s-1)*t**2 + (3-2*s)*t

# %% ../nbs/12_train_flow.ipynb #aa120006
@torch.no_grad()
def rk4_step(model, y, t, dt):
    """4th-order Runge-Kutta step for the learned velocity field."""
    t_  = torch.full((y.size(0), 1), t, device=y.device, dtype=y.dtype)
    k1 = model(y,             t_)
    k2 = model(y + dt*k1/2,   t_ + dt/2)
    k3 = model(y + dt*k2/2,   t_ + dt/2)
    k4 = model(y + dt*k3,     t_ + dt)
    return y + (dt/6)*(k1 + 2*k2 + 2*k3 + k4)

@torch.no_grad()
def euler_step(model, y, t, dt):
    t_ = torch.full((y.size(0), 1), t, device=y.device, dtype=y.dtype)
    return y + model(y, t_) * dt

